-- Replace the Chinese company overview with the supplied three paragraphs.
-- Change only the two About-page text fields, once; preserve later backend edits.
SET NAMES utf8mb4;
START TRANSACTION;
UPDATE site_settings SET configuration=JSON_SET(configuration,'$.about.description.zh',CONVERT( USING utf8mb4),'$.about.description2.zh',CONVERT( USING utf8mb4)) WHERE id='about-tzme' AND JSON_TYPE(JSON_EXTRACT(configuration,'$.about'))='OBJECT' AND NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-24-company-overview-zh-v1');
INSERT INTO app_migrations (id) SELECT '2026-10-24-company-overview-zh-v1' WHERE NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-24-company-overview-zh-v1');
COMMIT;
